 38→export function InlineQueryResult({ result }: { result: ToolCallResult }) {
 39→  const { t } = useTranslation();
 40→  const displayName = getToolDisplayName(result, t);
 41→  const inputDisplay = getToolInputDisplay(result);
 42→  const isSQLTool = isSQL(result);
 43→  const hasStructuredData = result.columns.length > 0;
 44→  const displayRows = result.rows.slice(0, MAX_DISPLAY_ROWS);
 45→
 46→  // Determine border color class
 47→  let variantClass = '';
 48→  if (result.error) variantClass = 'inline-query--error';
 49→  else if (result.command) variantClass = 'inline-query--bash';
 50→  else if (!isSQLTool && !result.sql) variantClass = 'inline-query--generic';
 51→
 52→  return (
 53→    <div className={`inline-query ${variantClass}`}>
 54→      {/* Tool label */}
 55→      <div className={`inline-query__label ${isSQLTool ? 'inline-query__label--sql' : result.command ? 'inline-query__label--bash' : 'inline-query__label--generic'}`}>
 56→        {displayName}
 57→      </div>
 58→
 59→      {/* Tool input */}
 60→      {inputDisplay && (
 61→        <div className="inline-query__sql">
 62→          <code>{inputDisplay}</code>
 63→        </div>
 64→      )}
 65→
 66→      {/* Error display */}
 67→      {result.error && (
 68→        <div className="inline-query__error">{result.error}</div>
 69→      )}
 70→
 71→      {/* SQL structured results */}
 72→      {!result.error && isSQLTool && hasStructuredData && (
 73→        <>
 74→          <div className="inline-query__table-wrapper">
 75→            <table className="inline-query__table">
 76→              <thead>
 77→                <tr>
 78→                  {result.columns.map((col) => (
 79→                    <th key={col}>{col}</th>
 80→                  ))}
 81→                </tr>
 82→              </thead>
 83→              <tbody>
 84→                {displayRows.map((row, i) => (
 85→                  <tr key={i}>
 86→                    {result.columns.map((col) => (
 87→                      <td key={col}>{String(row[col] ?? '')}</td>
 88→                    ))}
 89→                  </tr>
 90→                ))}
 91→              </tbody>
 92→            </table>
 93→          </div>
 94→          <div className="inline-query__meta">
 95→            {t('rowCount', { count: result.rowCount })}
 96→            {result.rowCount > MAX_DISPLAY_ROWS && ` ${t('showingCount', { count: MAX_DISPLAY_ROWS })}`}
 97→          </div>
 98→        </>
 99→      )}
100→
101→      {/* Text output for non-SQL tools */}
102→      {!result.error && result.output && (
